import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testRegression_property() public {
        address player1 = address(0x1234);
        address player2 = address(0x5678);
        vm.deal(player1, 100 wei);
        vm.deal(player2, 100 wei);

        vm.prank(player1);
        c.play{value: 10 wei}();

        vm.prank(player2);
        c.play{value: 10 wei}();

        assertTrue(c.pot() <= 20 wei);
    }
}
